public indirect enum Block: Codable, Sendable, Hashable {
	case paragraph([Inline])
	case heading(HeadingBlock)
	case quote([Block])
	case list(ListBlock)
	/// Preformatted text, shown monospaced.
	case code(String)
	case rule
	case table(TableBlock)

	enum CodingKeys: String, CodingKey, Codable {
		case paragraph,
			heading,
			quote,
			list,
			code,
			rule,
			table
	}

	private enum ContainerCodingKeys: String, CodingKey {
		case type, content
	}

	public init(from decoder: Decoder) throws {
		let container = try decoder.container(keyedBy: ContainerCodingKeys.self)
		if let type = try? container.decode(CodingKeys.self, forKey: .type) {
			switch type {
			case .paragraph:
				if let content = try? container.decode([Inline].self, forKey: .content) {
					self = .paragraph(content)
					return
				}
			case .heading:
				if let content = try? container.decode(HeadingBlock.self, forKey: .content) {
					self = .heading(content)
					return
				}
			case .quote:
				if let content = try? container.decode([Block].self, forKey: .content) {
					self = .quote(content)
					return
				}
			case .list:
				if let content = try? container.decode(ListBlock.self, forKey: .content) {
					self = .list(content)
					return
				}
			case .code:
				if let content = try? container.decode(String.self, forKey: .content) {
					self = .code(content)
					return
				}
			case .rule:
				self = .rule
				return
			case .table:
				if let content = try? container.decode(TableBlock.self, forKey: .content) {
					self = .table(content)
					return
				}
			}
		}
		throw DecodingError.typeMismatch(Block.self, DecodingError.Context(codingPath: decoder.codingPath, debugDescription: "Wrong type for Block"))
	}

	public func encode(to encoder: Encoder) throws {
		var container = encoder.container(keyedBy: ContainerCodingKeys.self)
		switch self {
		case .paragraph(let content):
			try container.encode(CodingKeys.paragraph, forKey: .type)
			try container.encode(content, forKey: .content)
		case .heading(let content):
			try container.encode(CodingKeys.heading, forKey: .type)
			try container.encode(content, forKey: .content)
		case .quote(let content):
			try container.encode(CodingKeys.quote, forKey: .type)
			try container.encode(content, forKey: .content)
		case .list(let content):
			try container.encode(CodingKeys.list, forKey: .type)
			try container.encode(content, forKey: .content)
		case .code(let content):
			try container.encode(CodingKeys.code, forKey: .type)
			try container.encode(content, forKey: .content)
		case .rule:
			try container.encode(CodingKeys.rule, forKey: .type)
		case .table(let content):
			try container.encode(CodingKeys.table, forKey: .type)
			try container.encode(content, forKey: .content)
		}
	}
}

