public enum Event: Codable, Sendable, Hashable {
	/// The shell is up; the core loads what it persisted.
	case appStarted
	/// The app came to the foreground; stale data is refreshed.
	case appBecameActive
	/// The web signed in through its own login form (`AuthMode::Cookie`); the core loads the
	/// new session. Native clients sign in through the core and never send it.
	case sessionStarted
	/// The web changed what the session shows through its own API calls (a profile edit, the
	/// admin settings) or had one rejected as signed out; the core reads the session again.
	/// Native clients make those calls through the core and never send it.
	case sessionChanged
	/// The user typed a server address on the add-server screen.
	case serverAddressSubmitted(ServerAddress)
	case serverRemoved(ServerRef)
	case passwordSignInSubmitted(PasswordSignIn)
	case pairingStarted(ServerRef)
	case pairingCancelled
	/// The shell opened a `couchverse://` link (a scanned QR code or a tapped link).
	case linkOpened(Link)
	case accountSelected(AccountRef)
	case signOutRequested(AccountRef)
	case devicesOpened
	case deviceRevoked(DeviceRef)
	case pairingApprovalOpened(UserCode)
	case pairingApproved(PairingApproval)
	case pairingDenied(UserCode)
	case displayLanguageChanged(LanguageChoice)
	/// A screen showing this surface appeared; the core loads it or, when cached, shows it
	/// and refreshes it.
	case screenOpened(Surface)
	case screenClosed(Surface)
	/// Pull to refresh.
	case refreshRequested(Surface)
	/// The user scrolled near the end of a listing.
	case browseMoreRequested(BrowseKey)
	/// The search field changed; the core waits for a pause in typing before searching.
	case searchChanged(SearchText)
	case watchlistChanged(WatchlistChange)
	case noticeDismissed(NoticeRef)
	/// Something that may have earned an achievement happened (playback finished a title).
	case achievementsCheckRequested(CheckRequest)
	/// The celebration on screen was seen.
	case celebrationDismissed
	/// The viewer's profile appears on public pages and leaderboards, or not.
	case profileVisibilityChanged(PublicChoice)
	case profileEditSubmitted(ProfileEdit)
	case passwordChangeSubmitted(PasswordForm)
	/// The user picked an image; the core asks the shell to upload it.
	case imageChosen(ImageChoice)
	case imageRemoved(ImageSlotRef)
	/// The player screen opened for a movie or an episode (or switched to another episode).
	case playRequested(PlayTarget)
	/// What the shell's player is doing: sent on every state change and about once a second
	/// while playing.
	case playerReported(PlayerReport)
	/// The player screen went away; the core saves progress and stops the stream.
	case playerClosed
	case qualityChosen(QualityChoice)
	case audioChosen(TrackChoice)
	case subtitlesChosen(TrackChoice)
	/// Play the next episode now instead of waiting for the countdown.
	case nextEpisodeRequested
	/// Hide the next-episode countdown; playback stops at the end.
	case nextEpisodeCancelled
	case shuffleToggled
	/// What this device can play, measured by the shell once per launch.
	case capabilitiesReported(Capabilities)

	enum CodingKeys: String, CodingKey, Codable {
		case appStarted,
			appBecameActive,
			sessionStarted,
			sessionChanged,
			serverAddressSubmitted,
			serverRemoved,
			passwordSignInSubmitted,
			pairingStarted,
			pairingCancelled,
			linkOpened,
			accountSelected,
			signOutRequested,
			devicesOpened,
			deviceRevoked,
			pairingApprovalOpened,
			pairingApproved,
			pairingDenied,
			displayLanguageChanged,
			screenOpened,
			screenClosed,
			refreshRequested,
			browseMoreRequested,
			searchChanged,
			watchlistChanged,
			noticeDismissed,
			achievementsCheckRequested,
			celebrationDismissed,
			profileVisibilityChanged,
			profileEditSubmitted,
			passwordChangeSubmitted,
			imageChosen,
			imageRemoved,
			playRequested,
			playerReported,
			playerClosed,
			qualityChosen,
			audioChosen,
			subtitlesChosen,
			nextEpisodeRequested,
			nextEpisodeCancelled,
			shuffleToggled,
			capabilitiesReported
	}

	private enum ContainerCodingKeys: String, CodingKey {
		case type, content
	}

	public init(from decoder: Decoder) throws {
		let container = try decoder.container(keyedBy: ContainerCodingKeys.self)
