/// A screen, panel or piece of state a shell renders from a view model.
public enum Surface: Codable, Sendable, Hashable {
	/// Where the app is: which account is active and what the shell should show at the root.
	case app
	/// The known servers and the add-server flow.
	case servers
	/// Every account on every server: the "Who's watching?" picker and the account switcher.
	case accounts
	/// Signing in to a server: password and pairing.
	case signIn
	/// The signed-in account's devices.
	case devices
	/// A pairing request this account is approving for another device.
	case pairingApproval
	/// The active account's session: user, features, display language and theme.
	case session
	/// A markdown document rendered safely; the content is the source.
	case markdown(String)
	case home
	/// A listing of movies, series or a genre.
	case browse(BrowseKey)
	/// A title's detail page; the content is its slug.
	case title(String)
	case genres
	case myList
	case search
	/// Transient notices for a toast or banner.
	case notices
	/// The viewer's rank badge and the achievement celebrations.
	case rank
	/// A member's profile; the content is the username.
	case profile(String)
	case leaderboard(LeaderboardKey)
	/// The viewer's profile, password and image saves.
	case profileEditor
	/// The player screen: sources, tracks, qualities, episodes and the next-episode countdown.
	case player

	enum CodingKeys: String, CodingKey, Codable {
		case app,
			servers,
			accounts,
			signIn,
			devices,
			pairingApproval,
			session,
			markdown,
			home,
			browse,
			title,
			genres,
			myList,
			search,
			notices,
			rank,
			profile,
			leaderboard,
			profileEditor,
			player
	}

	private enum ContainerCodingKeys: String, CodingKey {
		case type, content
	}

	public init(from decoder: Decoder) throws {
		let container = try decoder.container(keyedBy: ContainerCodingKeys.self)
		if let type = try? container.decode(CodingKeys.self, forKey: .type) {
			switch type {
			case .app:
				self = .app
				return
			case .servers:
				self = .servers
				return
			case .accounts:
				self = .accounts
				return
			case .signIn:
				self = .signIn
				return
			case .devices:
				self = .devices
				return
			case .pairingApproval:
				self = .pairingApproval
				return
			case .session:
				self = .session
				return
			case .markdown:
				if let content = try? container.decode(String.self, forKey: .content) {
					self = .markdown(content)
					return
				}
			case .home:
				self = .home
				return
			case .browse:
				if let content = try? container.decode(BrowseKey.self, forKey: .content) {
					self = .browse(content)
					return
				}
			case .title:
				if let content = try? container.decode(String.self, forKey: .content) {
					self = .title(content)
					return
				}
			case .genres:
				self = .genres
				return
			case .myList:
				self = .myList
				return
			case .search:
				self = .search
				return
			case .notices:
				self = .notices
				return
			case .rank:
				self = .rank
				return
			case .profile:
				if let content = try? container.decode(String.self, forKey: .content) {
					self = .profile(content)
					return
				}
			case .leaderboard:
				if let content = try? container.decode(LeaderboardKey.self, forKey: .content) {
					self = .leaderboard(content)
					return
				}
			case .profileEditor:
				self = .profileEditor
				return
			case .player:
				self = .player
				return
			}
		}
		throw DecodingError.typeMismatch(Surface.self, DecodingError.Context(codingPath: decoder.codingPath, debugDescription: "Wrong type for Surface"))
	}

	public func encode(to encoder: Encoder) throws {
		var container = encoder.container(keyedBy: ContainerCodingKeys.self)
		switch self {
		case .app:
			try container.encode(CodingKeys.app, forKey: .type)
		case .servers:
			try container.encode(CodingKeys.servers, forKey: .type)
		case .accounts:
			try container.encode(CodingKeys.accounts, forKey: .type)
		case .signIn:
			try container.encode(CodingKeys.signIn, forKey: .type)
		case .devices:
			try container.encode(CodingKeys.devices, forKey: .type)
		case .pairingApproval:
			try container.encode(CodingKeys.pairingApproval, forKey: .type)
		case .session:
			try container.encode(CodingKeys.session, forKey: .type)
		case .markdown(let content):
			try container.encode(CodingKeys.markdown, forKey: .type)
			try container.encode(content, forKey: .content)
		case .home:
			try container.encode(CodingKeys.home, forKey: .type)
		case .browse(let content):
			try container.encode(CodingKeys.browse, forKey: .type)
			try container.encode(content, forKey: .content)
		case .title(let content):
