public enum EffectOutput: Codable, Sendable, Hashable {
	case http(HttpResponse)
	/// The request never got an HTTP response (offline, DNS, TLS, timeout).
	case httpFailed(HttpFailure)
	case timerFired
	/// A store read; `None` when the key holds nothing.
	case stored(StoredValue)
	/// A store write or delete finished.
	case storeDone
	case storeFailed(StoreFailure)

	enum CodingKeys: String, CodingKey, Codable {
		case http,
			httpFailed,
			timerFired,
			stored,
			storeDone,
			storeFailed
	}

	private enum ContainerCodingKeys: String, CodingKey {
		case type, content
	}

	public init(from decoder: Decoder) throws {
		let container = try decoder.container(keyedBy: ContainerCodingKeys.self)
		if let type = try? container.decode(CodingKeys.self, forKey: .type) {
			switch type {
			case .http:
				if let content = try? container.decode(HttpResponse.self, forKey: .content) {
					self = .http(content)
					return
				}
			case .httpFailed:
				if let content = try? container.decode(HttpFailure.self, forKey: .content) {
					self = .httpFailed(content)
					return
				}
			case .timerFired:
				self = .timerFired
				return
			case .stored:
				if let content = try? container.decode(StoredValue.self, forKey: .content) {
					self = .stored(content)
					return
				}
			case .storeDone:
				self = .storeDone
				return
			case .storeFailed:
				if let content = try? container.decode(StoreFailure.self, forKey: .content) {
					self = .storeFailed(content)
					return
				}
			}
		}
		throw DecodingError.typeMismatch(EffectOutput.self, DecodingError.Context(codingPath: decoder.codingPath, debugDescription: "Wrong type for EffectOutput"))
	}

	public func encode(to encoder: Encoder) throws {
		var container = encoder.container(keyedBy: ContainerCodingKeys.self)
		switch self {
		case .http(let content):
			try container.encode(CodingKeys.http, forKey: .type)
			try container.encode(content, forKey: .content)
		case .httpFailed(let content):
			try container.encode(CodingKeys.httpFailed, forKey: .type)
			try container.encode(content, forKey: .content)
		case .timerFired:
			try container.encode(CodingKeys.timerFired, forKey: .type)
		case .stored(let content):
			try container.encode(CodingKeys.stored, forKey: .type)
			try container.encode(content, forKey: .content)
		case .storeDone:
			try container.encode(CodingKeys.storeDone, forKey: .type)
		case .storeFailed(let content):
			try container.encode(CodingKeys.storeFailed, forKey: .type)
			try container.encode(content, forKey: .content)
		}
	}
}

